<?php require 'config.php';require_login();$s=$pdo->prepare('SELECT b.*,f.airline,f.flight_no,f.origin,f.destination,f.departure FROM bookings b JOIN flights f ON f.id=b.flight_id WHERE b.user_id=? ORDER BY b.id DESC');$s->execute([$_SESSION['user_id']]);$rows=$s->fetchAll();?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>My tickets</h1><table><tr><th>Code</th><th>Flight</th><th>Date</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $b):?><tr><td><?=h($b['booking_code'])?></td><td><?=h($b['origin'])?> → <?=h($b['destination'])?></td><td><?=h($b['departure'])?></td><td><?=h($b['status'])?></td><td><a href="ticket.php?id=<?=$b['id']?>">View / Print</a> <?php if($b['status']==='CONFIRMED'):?>| <a href="cancel.php?id=<?=$b['id']?>" onclick="return confirm('Cancel this ticket?')">Cancel</a><?php endif;?></td></tr><?php endforeach;?></table></div></div></body></html>